import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.B_qehzBO.js";var i=JSON.parse(`{"title":"Backend & APIs — Services Built to Stay Up","description":"FastAPI, Gin, Laravel, .NET, Express — designing and operating backend services and APIs that survive real traffic.","frontmatter":{"title":"Backend & APIs — Services Built to Stay Up","description":"FastAPI, Gin, Laravel, .NET, Express — designing and operating backend services and APIs that survive real traffic."},"headers":[],"relativePath":"en/skills/backend/index.md","filePath":"en/skills/backend/index.md"}`),a={name:`en/skills/backend/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="backend-apis-—-services-built-to-stay-up" tabindex="-1">Backend &amp; APIs — Services Built to Stay Up <a class="header-anchor" href="#backend-apis-—-services-built-to-stay-up" aria-label="Permalink to “Backend &amp; APIs — Services Built to Stay Up”">​</a></h1><p>My backend philosophy is boring on purpose: clear contracts, explicit failure, and services that restart themselves without drama. The exciting part is what the services enable — free-tier AI infrastructure, proxy panels serving real users, bridges that turn web accounts into APIs.</p><h2 id="stacks-i-ship-with" tabindex="-1">Stacks I ship with <a class="header-anchor" href="#stacks-i-ship-with" aria-label="Permalink to “Stacks I ship with”">​</a></h2><table tabindex="0"><thead><tr><th>Stack</th><th>Sweet spot</th></tr></thead><tbody><tr><td>Python — FastAPI / Django</td><td>APIs, agents, async I/O bridges (GhostBrain, Hermes).</td></tr><tr><td>Go — Gin / stdlib</td><td>Single-binary services and CLIs (NetPilot, OmniRouter).</td></tr><tr><td>PHP — Laravel</td><td>Full products with auth, queues and admin panels.</td></tr><tr><td>C# — ASP.NET</td><td>Enterprise-style services and desktop backends.</td></tr><tr><td>Node — Express / Fastify</td><td>Edge Workers, real-time glue, rapid prototypes.</td></tr></tbody></table><h2 id="non-negotiables" tabindex="-1">Non-negotiables <a class="header-anchor" href="#non-negotiables" aria-label="Permalink to “Non-negotiables”">​</a></h2><ul><li><strong>Health endpoints</strong> on anything long-running — my own tooling (<a href="/Usf/en/projects/netpilot/">NetPilot</a>) monitors them.</li><li><strong>Graceful degradation</strong> — a dead upstream must degrade features, never take the process down.</li><li><strong>Structured logs</strong> from day one, because debugging by vibes does not scale past 2 AM.</li><li><strong>Contract tests</strong> for anything another system depends on — including agents.</li></ul><p>The pattern across my projects: the <a href="/Usf/en/projects/glm-free-api/">free-api bridges</a> handle hostile, rate-limited upstreams; <a href="/Usf/en/projects/taskflow-api/">TaskFlow API</a> handles multi-user state behind auth; the <a href="/Usf/en/projects/omnirouter/">routers</a> handle failure between them. Same principles, different pressure points.</p>`,7)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};